// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint112 _value, address _target, bytes memory _data) public {
        vm.assume(_target != address(c));
        vm.assume(_target != address(0));
        vm.assume(_value > 0);
        vm.deal(address(c), _value);
        uint256 balBefore = address(c).balance;
        vm.prank(c.owner());
        c.sendMoney(_target, _value, _data);
        assertEq(address(c).balance, balBefore - _value);
    }
}
